//! Reference gaits from motion capture, written by python/mocap.py. Do not edit.
//! CMU Graphics Lab Motion Capture Database, trials 07_04 07_01 07_12: one person walking
//! at 3 speeds. Each is one step, from the stance foot's heel strike to the swing
//! foot's, in 50 samples. Angles in radians, in the walker's joint conventions.
#![allow(clippy::approx_constant)] // measured angles, some near 1/π or log10(2) by chance

/// One captured walk, averaged into a single step.
pub struct Clip {
    /// Walking speed (m/s) and how long one step took (s).
    pub speed: f64,
    pub step_seconds: f64,
    /// Per sample: torso pitch about its mean; stance hip (thigh from vertical, in the
    /// world), knee, ankle; swing hip (world), knee, ankle; stance-side shoulder (upper
    /// arm from vertical, in the world), elbow; swing-side shoulder, elbow.
    pub step: [[f64; 11]; 50],
}

